import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse(`{"title":"handl_plugin_ext_test","description":"","frontmatter":{},"headers":[],"relativePath":"api/host/handl_plugin_ext_test/index.md","filePath":"api/host/handl_plugin_ext_test/index.md"}`),a={name:`api/host/handl_plugin_ext_test/index.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="handl-plugin-ext-test" tabindex="-1">handl_plugin_ext_test <a class="header-anchor" href="#handl-plugin-ext-test" aria-label="Permalink to “handl_plugin_ext_test”">​</a></h1><p><code>handl-plugin-ext-test</code> — the <code>test</code> capability adapter.</p><p>Exposes the <code>hnl test</code> runner (ADR-0089) through the <code>plugin-ext-*</code> capability seam, so a host can dispatch discovery + execution uniformly with <code>fmt</code>, <code>lint</code>, and <code>typecheck</code>.</p><p>The implementation is [<code>plugin::TestPlugin</code>], a thin adapter over [<code>hnl_engine_test</code>] — the <em>same</em> functions <code>host-cli</code> calls, so the capability path and the direct call cannot drift.</p><h1 id="division-of-responsibility" tabindex="-1">Division of responsibility <a class="header-anchor" href="#division-of-responsibility" aria-label="Permalink to “Division of responsibility”">​</a></h1><p>The capability is <strong>policy-free</strong>: it does not decide default paths (the caller passes the resolved list), does not choose the reporter&#39;s output stream, and does not set a process exit code. It returns structured results — including the <em>rendered</em> report, because the engine&#39;s report types are not <code>Serialize</code> — and the caller decides presentation.</p><p>The one exception is <code>cache</code>: the ADR-0089 on-disk result cache belongs to the runner, so <code>cache: true</code> loads and saves it here, at the runner&#39;s existing path (<code>.handl/cache/test-runner/cache.json</code> under the CWD).</p><h1 id="no-language-payload" tabindex="-1">No <code>language</code> payload <a class="header-anchor" href="#no-language-payload" aria-label="Permalink to “No language payload”">​</a></h1><p>As with <code>typecheck</code> (see <code>plugin-ext-typecheck</code>), the runner obtains its language from the single canonical assembly path, so there is no ADR-0124 divergence hazard between the CLI and this plugin — unlike <code>lint</code>, where the caller and the plugin assembled different &quot;canonical&quot; languages.</p><h2 id="modules" tabindex="-1">Modules <a class="header-anchor" href="#modules" aria-label="Permalink to “Modules”">​</a></h2><h3 id="handl-plugin-ext-test-1" tabindex="-1"><a href="./handl_plugin_ext_test.html"><code>handl_plugin_ext_test</code></a> <a class="header-anchor" href="#handl-plugin-ext-test-1" aria-label="Permalink to “handl_plugin_ext_test”">​</a></h3><p><em>1 module</em></p><h3 id="plugin" tabindex="-1"><a href="./plugin.html"><code>plugin</code></a> <a class="header-anchor" href="#plugin" aria-label="Permalink to “plugin”">​</a></h3><p><em>1 struct, 2 constants, 5 functions</em></p>`,14)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};